WITH base AS (SELECT *, SUBSTRING(city, 1, 3) AS city_prefix, FLOOR(rating) AS rating_whole FROM suppliers WHERE city IS NOT NULL AND city IS NULL), eligible AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.launch_date BETWEEN '2023-12-24' AND '2024-11-08')), filtered AS (SELECT *, LENGTH(city) AS city_length, COALESCE(city, 'N/A') AS city_filled FROM eligible WHERE rating < 2.4), latest_match AS (SELECT s.*, x.category FROM filtered s LEFT JOIN LATERAL (SELECT c.category FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) x ON TRUE), grouped AS (SELECT city, CASE WHEN city_length >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END AS city_length_tier, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS rating_per_jp, ROUND(AVG(city_length), 2) AS avg_city_length, APPROX_PERCENTILE(city_length, 0.9) AS city_length_p90 FROM latest_match GROUP BY ROLLUP (city, CASE WHEN city_length >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING avg_city_length > 0) SELECT city, city_length_tier, rating_per_jp, city_length_p90 FROM grouped;
